const body = $json.body || $json;
const p = body.payload || {};

// Um número por agora (Nuno) — acrescentar o da Beatriz aqui quando confirmado, sem tocar no resto do workflow.
const DESTINATARIOS = ['351911150025'];

// Link real do Calendly por serviço — a maioria das massagens regulares
// usa a mesma página (a cliente escolhe o tipo lá dentro); a Drenagem tem
// página própria por ser um protocolo diferente.
const LINKS_SERVICO = {
  'Essência Plena': 'https://calendly.com/geral-essencewellnesspt/agendar-massagem',
  'Puro Aroma': 'https://calendly.com/geral-essencewellnesspt/agendar-massagem',
  'Cera Quente': 'https://calendly.com/geral-essencewellnesspt/agendar-massagem',
  'Massagem Pré-Natal': 'https://calendly.com/geral-essencewellnesspt/agendar-massagem',
  'Drenagem Linfática': 'https://calendly.com/geral-essencewellnesspt/primeira-sessao-60min-avaliacao',
};
const LINK_GENERICO = 'https://calendly.com/geral-essencewellnesspt/agendar-massagem';

const nps = p.npsScore;
const linhas = [`📋 *${p.nomeCliente || 'Cliente'}* deu feedback: *${nps}/10*`];

if (typeof nps === 'number' && nps <= 6) {
  linhas.push('⚠️ Detratora — atenção');
  if (p.pontosMelhorar) linhas.push('O que podia ter sido melhor: ' + p.pontosMelhorar);
  if (p.comentario) linhas.push('O que precisaria para voltar: ' + p.comentario);
}

if (p.pontosPositivos) linhas.push('Gostou: ' + p.pontosPositivos);
if (p.motivoRegresso) linhas.push('Porque volta: "' + p.motivoRegresso + '"');
if (p.faltaParaDez) linhas.push('O que faltou para ser 10: ' + p.faltaParaDez);
if (p.quandoVoltar) linhas.push('Quer voltar: ' + p.quandoVoltar);
if (p.interesseServico) linhas.push('Interesse: ' + p.interesseServico);

if (p.pedidoContactoMarcacao) {
  linhas.push('');
  linhas.push('🌟 Pediu para tratares já da marcação!');
  const pref = [p.diaPreferido, p.horaPreferida].filter(Boolean).join(' ');
  if (pref) linhas.push('Prefere: ' + pref);
  if (p.telefone) linhas.push('Telefone: ' + p.telefone);

  const servicosInteresse = (p.interesseServico || '').split(',').map(s => s.trim()).filter(Boolean);
  const linksUnicos = [...new Set(servicosInteresse.map(s => LINKS_SERVICO[s]).filter(Boolean))];
  if (linksUnicos.length > 0) {
    linksUnicos.forEach(link => linhas.push('Marcar aqui: ' + link));
  } else {
    linhas.push('Marcar aqui: ' + LINK_GENERICO);
  }
}

const texto = linhas.join('\n');
return DESTINATARIOS.map(numero => ({ json: { numero, texto } }));

// Fallback: o WhatsApp falhou (Evolution API) — envia a MESMA mensagem por
// email em vez de a perder. Simples: sem despejo de JSON, sem aviso genérico
// de "WhatsApp desligado" (isso é só o WF15) — é só o conteúdo real.
const texto = $json.texto || $json.textoWhatsapp || '(sem conteúdo disponível — a sessão continua registada no CRM)';
return [{ json: {
  to: 'geral@essencewellnesspt.com',
  subject: '⚠️ WhatsApp falhou — Feedback — Notificações (terapeuta)',
  body: `O envio por WhatsApp falhou (Evolution API) — aqui fica a mesma mensagem, por email:

${texto}`,
} }];

